use core::net::SocketAddr;
use std::io::{BufRead, BufReader};
use std::os::unix::io::OwnedFd;
use std::process::Stdio;

use crate::common::{NixClient, NixStore, RealNixClient};

/// The path to the Cap'n Proto config file generated by `build.rs`.
const WORKERD_CONFIG: &str = env!("WORKERD_TEST_CONFIG");

/// Spawns a `workerd serve` process with the test config and returns the
/// socket address it's listening on.
///
/// The `workerd` process is killed when the returned [`WorkerdProcess`] is
/// dropped.
fn spawn_workerd() -> WorkerdProcess {
    // Create a pipe for workerd's `--control-fd`. The write end is passed to
    // workerd as fd 3, which it uses to report the listening port as a JSON
    // control message.
    let (read_end, write_end) = os_pipe::pipe().expect("failed to create pipe");

    let mut cmd = std::process::Command::new("workerd");
    cmd.args(["serve", WORKERD_CONFIG, "--control-fd", "3"]);
    cmd.stdin(Stdio::null());
    cmd.stdout(Stdio::null());
    cmd.stderr(Stdio::piped());

    // Map the write end of the pipe to fd 3 in the child process.
    let write_end_fd: OwnedFd = write_end.into();
    command_fds::CommandFdExt::fd_mappings(
        &mut cmd,
        vec![command_fds::FdMapping { parent_fd: write_end_fd, child_fd: 3 }],
    )
    .expect("failed to set up fd mappings");

    let child = cmd.spawn().expect("failed to spawn workerd");

    // Read the control message to discover the listening port.
    //
    // workerd writes JSON lines like:
    //   {"event":"listen","socket":"http","port":49152}
    let mut reader = BufReader::new(read_end);
    let mut line = String::new();

    reader
        .read_line(&mut line)
        .expect("failed to read control message from workerd");

    let msg: serde_json::Value = serde_json::from_str(line.trim())
        .unwrap_or_else(|e| {
            panic!("failed to parse workerd control message {line:?}: {e}")
        });

    assert_eq!(
        msg["event"].as_str(),
        Some("listen"),
        "unexpected control message: {msg}"
    );

    let port = msg["port"]
        .as_u64()
        .unwrap_or_else(|| panic!("missing port in control message: {msg}"))
        as u16;

    let addr = SocketAddr::from(([127, 0, 0, 1], port));

    WorkerdProcess { child, addr }
}

struct WorkerdProcess {
    child: std::process::Child,
    addr: SocketAddr,
}

impl Drop for WorkerdProcess {
    fn drop(&mut self) {
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

#[tokio::test]
async fn copy_to_and_from_cache() {
    let workerd = spawn_workerd();

    let nix = RealNixClient::new();

    let store_path = nix.store().add_file("hello-world", b"hello world").await;

    // Push to the cache served by workerd (backed by in-memory R2).
    nix.copy([store_path.clone()])
        .to(workerd.addr, "user", "cache")
        .await
        .unwrap();

    // Delete from the local Nix store.
    nix.store().delete(&store_path).await;
    assert!(!nix.store().contains(&store_path).await);

    // Pull from the cache — this exercises the full round-trip through
    // workerd's R2 storage.
    nix.copy([store_path.clone()])
        .from(workerd.addr, "user", "cache")
        .await
        .unwrap();

    assert!(nix.store().contains(&store_path).await);
}
